                        "pgid": os.getpgrp(),
                        "sid": os.getsid(0),
                    }
                    worker_capture._write(control, json.dumps(message).encode() + b"\n", deadline)
                # No helper is created. TERM/KILL and child lifetime remain real.
                while True:
                    signal.pause()
            finally:
                os._exit(70)

        def waitpid(pid, flags):
            now = time.monotonic()
            admitted = _admitted("_reap")
            calls.append(
                {
                    "operation": "waitpid",
                    "pid": pid,
                    "flags": flags,
                    "time": now,
                    "admitted": admitted,
                }
