                {
                    "operation": "killpg",
                    "pid": pid,
                    "signal": int(sig),
                    "time": time.monotonic(),
                    "admitted": _admitted("_signal"),
                }
            )
            return original_killpg(pid, sig)

        def monotonic():
            return end if cleanup_cutoff else original_monotonic()

